#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// include common Polybench definitions (NI, NJ, NK, NL, DATA_TYPE, etc.)
#include "defines.hpp"

// include benchmark-specific definitions for 2mm
#include "2mm.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize arrays A, B, C, D in the same way as the original C version.
 *
 * C layout:
 *   A[ni][nk] -> Buffer A(k, i)  with shape (nk, ni)
 *   B[nk][nj] -> Buffer B(j, k)  with shape (nj, nk)
 *   C[nj][nl] -> Buffer C(l, j)  with shape (nl, nj)
 *   D[ni][nl] -> Buffer D(l, i)  with shape (nl, ni)
 */
static void init_array(int ni, int nj, int nk, int nl,
                       num_t *alpha,
                       num_t *beta,
                       Halide::Buffer<num_t, 2> A,
                       Halide::Buffer<num_t, 2> B,
                       Halide::Buffer<num_t, 2> C,
                       Halide::Buffer<num_t, 2> D) {
    *alpha = (num_t)1.5;
    *beta  = (num_t)1.2;

    Var i("i"), j("j"), k("k"), l("l");
    Func init_A("init_A"), init_B("init_B"), init_C("init_C"), init_D("init_D");

    // A[i][j] = (DATA_TYPE) ((i*j+1) % ni) / ni;
    // A is stored as A(k, i) with shape (nk, ni)
    init_A(k, i) = cast<num_t>(((i * k + 1) % ni)) / cast<int>(ni);

    // B[i][j] = (DATA_TYPE) (i*(j+1) % nj) / nj;
    // B is stored as B(j, k) with shape (nj, nk)
    init_B(j, k) = cast<num_t>(((k * (j + 1)) % nj)) / cast<int>(nj);

    // C[i][j] = (DATA_TYPE) ((i*(j+3)+1) % nl) / nl;
    // C is stored as C(l, j) with shape (nl, nj)
    init_C(l, j) = cast<num_t>(((j * (l + 3) + 1) % nl)) / cast<int>(nl);

    // D[i][j] = (DATA_TYPE) (i*(j+2) % nk) / nk;
    // D is stored as D(l, i) with shape (nl, ni)
    init_D(l, i) = cast<num_t>(((i * (l + 2)) % nk)) / cast<int>(nk);

    // ------------------------------------------------------------------
    // Simple but effective schedule for initialization:
    //   - Parallelize along the slower-varying dimension (rows)
    //   - Vectorize along the contiguous dimension (columns)
    // ------------------------------------------------------------------
    Target target = get_jit_target_from_environment();
    int vec_width = target.natural_vector_size(type_of<num_t>());
    if (vec_width < 1) vec_width = 8;  // reasonable fallback

    // A(k, i): i is outer (rows), k is inner (contiguous) -> parallel(i), vectorize(k)
    init_A.parallel(i).vectorize(k, vec_width);

    // B(j, k): j is outer (rows), k is inner (contiguous) -> parallel(j), vectorize(k)
    init_B.parallel(j).vectorize(k, vec_width);

    // C(l, j): j is outer (rows), l is inner (contiguous) -> parallel(j), vectorize(l)
    init_C.parallel(j).vectorize(l, vec_width);

    // D(l, i): i is outer (rows), l is inner (contiguous) -> parallel(i), vectorize(l)
    init_D.parallel(i).vectorize(l, vec_width);

    // Realize into the provided Buffers
    init_A.realize(A);
    init_B.realize(B);
    init_C.realize(C);
    init_D.realize(D);
}

int main(int argc, char *argv[]) {
    // Problem sizes
    int ni = NI;
    int nj = NJ;
    int nk = NK;
    int nl = NL;

    // Scalar parameters
    num_t alpha;
    num_t beta;

    // Buffers corresponding to the C arrays:
    //
    // A[ni][nk] -> A(k, i)
    // B[nk][nj] -> B(j, k)
    // C[nj][nl] -> C(l, j)
    // D[ni][nl] -> D(l, i)
    // tmp[ni][nj] -> tmp(j, i)  (logical; not explicitly allocated)
    Halide::Buffer<num_t, 2> A(nk, ni);
    Halide::Buffer<num_t, 2> B(nj, nk);
    Halide::Buffer<num_t, 2> C(nl, nj);
    Halide::Buffer<num_t, 2> D(nl, ni);

    // ImageParams to pass the buffers into the Halide pipeline
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam D_param(type_of<num_t>(), 2, "D_param");

    // Initialize data (equivalent to init_array in the C version)
    init_array(ni, nj, nk, nl, &alpha, &beta, A, B, C, D);

    // Bind buffers to ImageParams
    A_param.set(A);
    B_param.set(B);
    C_param.set(C);
    D_param.set(D);

    // ------------------------------------------------------------------------
    // Halide definition of the 2mm kernel:
    //
    // Original C:
    //   /* D := alpha*A*B*C + beta*D */
    //   for (i)
    //     for (j)
    //       tmp[i][j] = 0;
    //       for (k)
    //         tmp[i][j] += alpha * A[i][k] * B[k][j];
    //
    //   for (i)
    //     for (j)
    //       D[i][j] *= beta;
    //       for (k)
    //         D[i][j] += tmp[i][k] * C[k][j];
    //
    // Mapping to Halide coordinates:
    //   i -> row index       (second dimension)
    //   j -> column index of tmp and intermediate (first dimension)
    //   l -> column index of final D and C        (first dimension)
    //   k -> reduction indices (nk for tmp, nj for D)
    //
    // Buffers:
    //   tmp(j, i)   corresponds to tmp[i][j]
    //   A_param(k,i) corresponds to A[i][k]
    //   B_param(j,k) corresponds to B[k][j]
    //   C_param(l,j) corresponds to C[j][l]
    //   D_param(l,i) corresponds to D[i][l]
    // ------------------------------------------------------------------------

    Var i("i"), j("j"), l("l");
    RDom k_AB(0, A_param.dim(0).extent(), "k_AB");   // reduction over nk
    RDom k_DC(0, C_param.dim(1).extent(), "k_DC");   // reduction over nj

    Func tmp_func("tmp");
    Func D_func("D");

    // tmp[i][j] accumulation: tmp(j, i)
    tmp_func(j, i) = cast<num_t>(0);
    tmp_func(j, i) += Expr(alpha) * A_param(k_AB, i) * B_param(j, k_AB);

    // D[i][l] update: D(l, i)
    D_func(l, i) = Expr(beta) * D_param(l, i);
    D_func(l, i) += tmp_func(k_DC, i) * C_param(l, k_DC);

    // ------------------------------------------------------------------------
    // Scheduling
    //
    // High-level goals:
    //   - Exploit data locality in both multiplications.
    //   - Parallelize across rows (i), which are independent.
    //   - Vectorize across the innermost x-dimension (j or l), which
    //     is contiguous in memory for all our Buffers.
    //   - Avoid materializing tmp for the entire domain at once:
    //     compute each row of tmp on-demand for the current row of D.
    //
    // Layout recap:
    //   tmp(j, i) : j is x (contiguous), i is y
    //   D(l,  i) : l is x (contiguous), i is y
    //   C(l,  j) : l is x (contiguous), j is y
    //
    // Strategy:
    //   - D_func is compute_root().
    //   - For each row i of D, compute the entire row tmp(:, i)
    //     via tmp_func.compute_at(D_func, i); this keeps tmp in cache
    //     and avoids a separate full pass over tmp.
    //   - Parallelize D over i (rows).
    //   - Vectorize over l (columns) in D and over j in tmp, using
    //     the natural vector width of the host for num_t.
    // ------------------------------------------------------------------------

    Target target = get_jit_target_from_environment();
    int vec_width = target.natural_vector_size(type_of<num_t>());
    if (vec_width < 1) vec_width = 8;  // fallback if detection fails

    // Schedule D (final result)
    D_func.compute_root();

    // Parallelize across independent rows i, vectorize across l (x)
    D_func.parallel(i).vectorize(l, vec_width);

    // For the update step of D, we want loops of the form:
    //   for i (parallel)
    //     for l (vectorized)
    //       for k_DC (reduction)
    //
    // So we reorder the update variables accordingly, then apply the
    // same parallel + vectorization decisions.
    D_func.update()
        .reorder(k_DC, l, i)   // innermost: k_DC, then l, then i
        .parallel(i)
        .vectorize(l, vec_width);

    // Schedule tmp:
    //
    // tmp is consumed only by D, and for a given row i of D we need
    // all j in [0, nj). We compute exactly that region on-demand:
    //   for each i row of D, compute tmp(:, i) once and reuse it
    //   across all l and k_DC for that row.
    //
    // This improves locality and avoids a separate pass over tmp.
    tmp_func.compute_at(D_func, i);

    // In tmp's pure definition and update, j is the x-dimension:
    // vectorize across j, and keep i as a serial loop outside.
    tmp_func.vectorize(j, vec_width);

    tmp_func.update()
        .reorder(k_AB, j, i)   // for i: for j (vectorized): for k_AB (reduction)
        .vectorize(j, vec_width);

    // ------------------------------------------------------------------------
    // JIT compile and run
    // ------------------------------------------------------------------------

    D_func.compile_jit(target);

    auto start = std::chrono::high_resolution_clock::now();

    // Run the kernel: result is written into D
    D_func.realize(D);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result matrix, similar to print_array in C.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < ni; ii++) {
            for (int jj = 0; jj < nl; jj++) {
                // D(ii, jj) in C is D(l = jj, i = ii) in Halide
                std::cerr << D(jj, ii) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
