    // Schedule for initialization
    //
    // We exploit the fact that the first dimension (x) is contiguous
    // in memory, so we vectorize across it and parallelize across the
    // second dimension (y). This keeps initialization fast without
    // complicating the main kernel.
    // ------------------------------------------------------------------
    Target init_target = get_jit_target_from_environment();
    const int vec = init_target.natural_vector_size(type_of<num_t>());

    init_A.compute_root()
          .parallel(i)
          .vectorize(k, vec);
    init_B.compute_root()
          .parallel(k)
          .vectorize(j, vec);
    init_C.compute_root()
          .parallel(j)
          .vectorize(l, vec);
    init_D.compute_root()
          .parallel(i)
          .vectorize(l, vec);

