    // arrays, so we vectorize across that dimension.
    // ------------------------------------------------------------------------

    Var i("i"), j("j"), l("l");
    RDom k_AB(0, A_param.dim(0).extent(), "k_AB");   // reduction over nk
    RDom k_DC(0, C_param.dim(1).extent(), "k_DC");   // reduction over nj

    Func tmp_func("tmp");
    Func D_func("D");

    // tmp[i][j] accumulation: tmp(j, i)
    tmp_func(j, i) = cast<num_t>(0);
    tmp_func(j, i) += Expr(alpha) * A_param(k_AB, i) * B_param(j, k_AB);

    // D[i][l] update: D(l, i)
    D_func(l, i) = Expr(beta) * D_param(l, i);
    D_func(l, i) += tmp_func(k_DC, i) * C_param(l, k_DC);

    // ------------------------------------------------------------------------
    // Scheduling
    //
    // Goals:
    //   - Keep inner loops over the contiguous dimension for good
    //     vectorization and cache line utilization.
    //   - Parallelize across the outer (row) dimension i to exploit
    //     many cores (32+ cores on the target system).
    //   - Preserve the original mathematical result up to normal
    //     floating‑point reordering effects.
    //
    // Layout recap:
    //   tmp(j, i) : j is x (contiguous), i is y
    //   D(l,  i)  : l is x (contiguous), i is y
    //
    // We therefore:
    //   * Vectorize across j in tmp and across l in D.
    //   * Parallelize across i in both tmp and D.
    //
    // For the reduction updates we reorder loops so that the
    // vectorized dimension is innermost, and the reduction RDom is
    // just outside or inside as appropriate. The reductions are
    // associative/commutative (sum of products), so changing the
    // loop order is safe except for benign FP round‑off differences.
    // ------------------------------------------------------------------------

    Target target = get_jit_target_from_environment();
    const int vec = target.natural_vector_size(type_of<num_t>());

    // --- tmp: pure stage ---
    // Loop order: for i (parallel) { for j (vectorized) { ... } }
    tmp_func
        .compute_root()
        .reorder(j, i)          // j (x) innermost, i (y) outermost
        .parallel(i)
        .vectorize(j, vec);

    // --- tmp: reduction update ---
    //
    // We want loops:
    //   for i (parallel)
    //     for k_AB
    //       for j (vectorized)
    //
    // so we reorder to (j, k_AB, i), then parallelize i and
    // vectorize j.
    tmp_func
        .update()
        .reorder(j, k_AB, i)
        .parallel(i)
        .vectorize(j, vec);

    // --- D: pure stage ---
    // Loop order: for i (parallel) { for l (vectorized) { ... } }
    D_func
        .compute_root()
        .reorder(l, i)          // l (x) innermost, i (y) outermost
        .parallel(i)
        .vectorize(l, vec);

    // --- D: reduction update ---
    //
    // Desired loops:
    //   for i (parallel)
    //     for k_DC
    //       for l (vectorized)
    //
    // so reorder to (l, k_DC, i), then parallelize i and vectorize l.
    D_func
        .update()
        .reorder(l, k_DC, i)
        .parallel(i)
        .vectorize(l, vec);

    // ------------------------------------------------------------------------
    // JIT compile and run
    // ------------------------------------------------------------------------

    D_func.compile_jit(target);

    auto start = std::chrono::high_resolution_clock::now();

    // Run the kernel: result is written into D
    D_func.realize(D);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result matrix, similar to print_array in C.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < ni; ii++) {
            for (int jj = 0; jj < nl; jj++) {
                // D(ii, jj) in C is D(l = jj, i = ii) in Halide
                std::cerr << D(jj, ii) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
