    // Scheduling for initialization:
    // - Vectorize along the innermost (x) dimension for good SIMD usage.
    // - Parallelize along the outer (y) dimension.
    // Initialization is cheap relative to the main kernel, but this
    // makes large problem sizes scale well across cores too.
    // ----------------------------------------------------------------------
    Target target = get_jit_target_from_environment();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    init_A.compute_root()
          .parallel(i)
          .vectorize(k, vec_width);

    init_B.compute_root()
          .parallel(k)
          .vectorize(j, vec_width);

    init_C.compute_root()
          .parallel(j)
          .vectorize(l, vec_width);

    init_D.compute_root()
          .parallel(i)
          .vectorize(l, vec_width);

