    //
    // A[ni][nk] -> A(k, i)
    // B[nk][nj] -> B(j, k)
    // C[nj][nl] -> C(l, j)
    // D[ni][nl] -> D(l, i)
    // tmp[ni][nj] -> tmp(j, i)
    Halide::Buffer<num_t, 2> A(nk, ni);
    Halide::Buffer<num_t, 2> B(nj, nk);
    Halide::Buffer<num_t, 2> C(nl, nj);
    Halide::Buffer<num_t, 2> D(nl, ni);
    Halide::Buffer<num_t, 2> tmp(nj, ni);

    // ImageParams to pass the buffers into the Halide pipeline
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam D_param(type_of<num_t>(), 2, "D_param");

    // Initialize data (equivalent to init_array in the C version)
    init_array(ni, nj, nk, nl, &alpha, &beta, A, B, C, D);

    // Bind buffers to ImageParams
    A_param.set(A);
    B_param.set(B);
    C_param.set(C);
    D_param.set(D);

    // ------------------------------------------------------------------------
    // Halide definition of the 2mm kernel:
    //
    // Original C:
    //   /* D := alpha*A*B*C + beta*D */
    //   for (i)
    //     for (j)
    //       tmp[i][j] = 0;
    //       for (k)
    //         tmp[i][j] += alpha * A[i][k] * B[k][j];
    //
    //   for (i)
    //     for (j)
    //       D[i][j] *= beta;
    //       for (k)
    //         D[i][j] += tmp[i][k] * C[k][j];
    //
    // Mapping to Halide coordinates:
    //   i -> row index  (second dimension)
    //   j -> column index for tmp and D (first dimension)
    //   k -> reduction indices (nk for tmp, nj for D)
    //
    // Buffers:
    //   tmp(j, i)   corresponds to tmp[i][j]
    //   A_param(k,i) corresponds to A[i][k]
    //   B_param(j,k) corresponds to B[k][j]
    //   C_param(l,j) corresponds to C[j][l]
    //   D_param(l,i) corresponds to D[i][l]
    // ------------------------------------------------------------------------

    Var i("i"), j("j"), l("l");
    RDom k_AB(0, A_param.dim(0).extent(), "k_AB");   // reduction over nk
    RDom k_DC(0, C_param.dim(1).extent(), "k_DC");   // reduction over nj

    Func tmp_func("tmp");
    Func D_func("D");

    Expr alpha_expr(alpha);
    Expr beta_expr(beta);

    // tmp[i][j] accumulation: tmp(j, i)
    tmp_func(j, i) = cast<num_t>(0);
    tmp_func(j, i) += alpha_expr * A_param(k_AB, i) * B_param(j, k_AB);

    // D[i][l] update: D(l, i)
    D_func(l, i) = cast<num_t>(beta_expr) * D_param(l, i);
    D_func(l, i) += tmp_func(k_DC, i) * C_param(l, k_DC);

    // ------------------------------------------------------------------------
    // Scheduling
    //
    // Goals:
    //  - Good cache locality for all three matrices.
    //  - Reuse tmp(i, :) across all l when forming D(i, l) (AB row reused
    //    against many columns of C).
    //  - Parallelize across rows of D (i dimension).
    //  - Vectorize across contiguous memory directions:
    //      * j for tmp (tmp(j, i) has j as fast dimension),
    //      * l for D (D(l, i) has l as fast dimension).
    //
    // High-level execution we want:
    //
    //   for tile of rows io:
    //     parallel over io
    //       for each row ii within tile:
    //         compute tmp_func(:, i)   // AB row for this i
    //         scale D(i, :) by beta
    //         for each k_DC:
    //           D(i, :) += tmp(i, k_DC) * C(k_DC, :)
    //
    // tmp_func is therefore scheduled to be computed inside the row-loop of D,
    // so we never materialize the full tmp matrix at once.
    // ------------------------------------------------------------------------

    Target target = get_jit_target_from_environment();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // Tune tile size along i (rows of D and tmp).
    const int tile_i = 32;

    Var io("io"), ii("ii");

    // --- Schedule for D_func (final output) ---

    D_func.compute_root();

    // Split i into tiles [io][ii], with l innermost, and parallelize tiles.
    // Loop order (pure step): for io, for ii, for l.
    D_func
        .split(i, io, ii, tile_i)
        .reorder(l, ii, io)
        .parallel(io)
        .vectorize(l, vec_width);

    // Update step: for each row-tile and row within it,
    // iterate over k_DC (columns of tmp / rows of C), and inside that
    // iterate over l (columns of D) with vectorization.
    //
    // Loop order (update step):
    //   for io (parallel)
    //     for ii
    //       for k_DC
    //         for l (vectorized)
    D_func.update()
        .split(i, io, ii, tile_i)
        .reorder(l, k_DC, ii, io)   // args are given from inner to outer
        .parallel(io)
        .vectorize(l, vec_width);

    // --- Schedule for tmp_func (intermediate A*B) ---

    // Compute tmp per row of D within the tiled row-loop.
    // This means:
    //   - Only the rows of tmp actually needed for a given i are computed.
    //   - Those rows are reused across all l for that i when computing D.
    //
    // We place tmp at the level 'ii' (row inside a tile), so each worker
    // thread working on a tile computes the necessary rows of tmp locally.
    tmp_func
        .compute_at(D_func, ii)
        .vectorize(j, vec_width);

    // For the reduction, we want:
    //   for k_AB:
    //     for j (vectorized):
    //       tmp(j, i) += alpha * A(k_AB, i) * B(j, k_AB);
    //
    // This:
    //   - iterates k_AB in the outer loop, letting us traverse C's
    //     producer B(j, k_AB) with j as the fast (contiguous) dimension.
    //   - vectorizes across j, which is contiguous in tmp and B.
    tmp_func.update()
        .reorder(j, k_AB)  // inner j, then k_AB, outer i from compute_at
        .vectorize(j, vec_width);

    // ------------------------------------------------------------------------
    // JIT compile and run
    // ------------------------------------------------------------------------

    D_func.compile_jit(target);

    auto start = std::chrono::high_resolution_clock::now();

    // Run the kernel: result is written into D
    D_func.realize(D, target);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result matrix, similar to print_array in C.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < ni; ii++) {
            for (int jj = 0; jj < nl; jj++) {
                // D(ii, jj) in C is D(l = jj, i = ii) in Halide
                std::cerr << D(jj, ii) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
