    //   - B:     dim 0 = j (stride 1), dim 1 = k
    //
    // We parallelize across i (rows), and vectorize across j (columns).
    // In the reduction update, we reorder loops to
    //   for i_outer, i_inner, k_AB, j
    // so that for each (i,k_AB) we sweep j contiguously across B(j,k_AB)
    // and tmp(j,i), which is cache-friendly and vectorizable.

    Var i_outer_tmp("i_outer_tmp"), i_inner_tmp("i_inner_tmp");

    tmp_func
        .compute_root()
        // Split rows i into outer (for parallelism) and inner.
        .split(i, i_outer_tmp, i_inner_tmp, i_chunk)
        // Reorder so that j is innermost, then the inner part of i,
        // and finally the outer part of i.
        .reorder(j, i_inner_tmp, i_outer_tmp)
        // Parallelize across row-chunks.
        .parallel(i_outer_tmp)
        // Vectorize across contiguous j.
        .vectorize(j, vec_width);

    tmp_func.update()
        // Reorder update loops to:
        //   i_outer_tmp (outer), i_inner_tmp, k_AB, j (innermost)
        // This gives:
        //   for i_outer
        //     for i_inner
        //       for k_AB
        //         for j (vectorized)
        .reorder(j, k_AB, i_inner_tmp, i_outer_tmp)
        .parallel(i_outer_tmp)
        .vectorize(j, vec_width);

    // -----------------------
    // Schedule for D_func
    // -----------------------
    //
    // D(l, i) = beta * D_param(l, i) +
    //           sum_j tmp(j, i) * C(l, j)
    //
    // Memory layout:
    //   - D: dim 0 = l (stride 1), dim 1 = i
    //   - tmp: dim 0 = j (stride 1), dim 1 = i
    //   - C: dim 0 = l (stride 1), dim 1 = j
    //
    // For best locality in the update:
    //   - We want l innermost so that C(l, j) and D(l, i) are contiguous.
    //   - We parallelize across i (rows) again.
    //   - We vectorize across l.

    Var i_outer_D("i_outer_D"), i_inner_D("i_inner_D");

    D_func
        .compute_root()
        // Split i into outer and inner pieces for parallelism.
        .split(i, i_outer_D, i_inner_D, i_chunk)
        // For the pure definition, use loop order:
        //   i_outer_D (outer), i_inner_D, l (innermost)
        .reorder(l, i_inner_D, i_outer_D)
        .parallel(i_outer_D)
        .vectorize(l, vec_width);

    D_func.update()
        // For the update definition, re-order to:
        //   i_outer_D (outer), i_inner_D, k_DC, l (innermost)
        // so that for each (i,k_DC) we sweep l contiguously across
        // C(l, k_DC) and D(l, i).
        .reorder(l, k_DC, i_inner_D, i_outer_D)
        .parallel(i_outer_D)
        .vectorize(l, vec_width);

    // ------------------------------------------------------------------------
    // JIT compile and run
    // ------------------------------------------------------------------------

    D_func.compile_jit(target);

    auto start = std::chrono::high_resolution_clock::now();

    // Run the kernel: result is written into D
    D_func.realize(D);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result matrix, similar to print_array in C.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < ni; ii++) {
            for (int jj = 0; jj < nl; jj++) {
                // D(ii, jj) in C is D(l = jj, i = ii) in Halide
                std::cerr << D(jj, ii) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
